"use client";

import { cn } from "cn";
import type { ClipboardStatus } from "@/hooks/use-clipboard";
import {
  type IconInput,
  type IconNode,
  MorphIcon,
  type MorphIconProps,
} from "@/components/ui/morph-icon";

const copyShape: IconNode = [
  ["rect", { width: 14, height: 14, x: 8, y: 8, rx: 2, ry: 2 }],
  ["path", { d: "M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2" }],
];
const checkShape: IconNode = [["path", { d: "m20 6-11 11-5-5" }]];
const errorShape: IconNode = [["path", { d: "m18 6-12 12M6 6l12 12" }]];
const pendingShape: IconNode = [["path", { d: "M12 2a10 10 0 1 0 10 10" }]];

type CopyIconProps = Omit<
  MorphIconProps,
  "icon" | "from" | "to" | "progress"
> & {
  status?: ClipboardStatus;
  copied?: boolean;
  error?: boolean;
  pending?: boolean;
  idleIcon?: IconInput;
};

function CopyIcon({
  status,
  copied = false,
  error = false,
  pending = false,
  className,
  idleIcon = copyShape,
  ...props
}: CopyIconProps) {
  let state: ClipboardStatus = status ?? "idle";
  if (status === undefined) {
    if (error) state = "error";
    else if (pending) state = "pending";
    else if (copied) state = "copied";
  }
  const icon = {
    idle: idleIcon,
    pending: pendingShape,
    copied: checkShape,
    error: errorShape,
  }[state];
  return (
    <MorphIcon
      icon={icon}
      data-slot="copy-icon"
      data-copy-state={state}
      className={cn(
        state === "pending" && "animate-spin motion-reduce:animate-none",
        state === "copied" && "text-primary",
        state === "error" && "text-destructive",
        className,
      )}
      {...props}
    />
  );
}

export type { CopyIconProps };
export { CopyIcon };

"use client";

import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva } from "class-variance-authority";
import { cn } from "cn";
import type { ReactNode } from "react";
import { type ClipboardOptions, useClipboard } from "@/hooks/use-clipboard";
import { CopyIcon } from "@/components/ui/copy-icon";

type CopyTextProps = Omit<
  ButtonPrimitive.Props,
  "children" | "onCopy" | "value" | "variant" | "size"
> &
  ClipboardOptions & {
    children: ReactNode;
    value?: string;
    variant?: "default" | "muted";
    size?: "sm" | "default";
    truncate?: boolean;
    iconVisibility?: "hover" | "always";
  };

const copyTextVariants = cva(
  "group/copy-text inline-flex min-w-0 max-w-full select-text items-center gap-1.5 rounded-sm border-0 bg-transparent p-0 align-baseline font-normal outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed disabled:opacity-50 data-[copy-status=pending]:disabled:opacity-100",
  {
    variants: {
      variant: {
        default: "text-foreground",
        muted:
          "text-muted-foreground hover:text-foreground focus-visible:text-foreground",
      },
      size: {
        default: "text-sm leading-5",
        sm: "text-xs leading-4",
      },
    },
    defaultVariants: { variant: "default", size: "default" },
  },
);

function CopyText({
  children,
  value,
  variant = "default",
  size = "default",
  truncate = true,
  iconVisibility = "hover",
  disabled = false,
  resetDelay,
  onCopy,
  onCopyError,
  feedback,
  labels,
  onClick,
  className,
  ...props
}: CopyTextProps) {
  const text = value ?? (typeof children === "string" ? children : null);
  if (text === null)
    throw new Error("CopyText requires value when children is not a string.");
  const { status, message, copy } = useClipboard(text, {
    disabled,
    resetDelay,
    onCopy,
    onCopyError,
    feedback,
    labels,
  });
  return (
    <ButtonPrimitive
      {...props}
      type="button"
      disabled={disabled || status === "pending"}
      data-slot="copy-text"
      data-copy-status={status}
      aria-busy={status === "pending"}
      aria-label={props["aria-label"] ?? labels?.copy ?? `Copy ${text}`}
      className={cn(copyTextVariants({ variant, size }), className)}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) void copy();
      }}
    >
      <code className={cn("min-w-0 font-mono", truncate && "truncate")}>
        {children}
      </code>
      <span
        aria-hidden="true"
        className={cn(
          "relative inline-flex size-3.5 shrink-0 items-center justify-center transition-opacity motion-reduce:transition-none",
          status === "idle" &&
            iconVisibility === "hover" &&
            "opacity-0 group-focus-within/copy-text:opacity-100 group-focus-within:opacity-100 group-hover/copy-text:opacity-100 group-hover:opacity-100 [@media(hover:none)]:opacity-100",
        )}
      >
        <CopyIcon status={status} className="size-3.5" />
      </span>
      <span role="status" className="sr-only">
        {status === "idle" ? "" : message}
      </span>
    </ButtonPrimitive>
  );
}

export type { CopyTextProps };

export { CopyText, copyTextVariants };

"use client";

import {
  createContext,
  type ReactNode,
  use,
  useCallback,
  useEffect,
  useRef,
} from "react";
import { type HapticKind, haptic } from "@/lib/haptics";
import {
  createTickPlayer,
  type TickPlayer,
  type TickVariant,
} from "@/lib/tick-sound";

/**
 * Per-component feedback switch. `true` plays haptics and sound, `"haptic"` or
 * `"sound"` plays only that one, `false` stays silent, and leaving it unset
 * follows the nearest `FeedbackProvider`.
 */
export type FeedbackOption = boolean | "haptic" | "sound";

interface FeedbackSettings {
  haptics: boolean;
  sound: boolean;
}

// Silent unless asked: a FeedbackProvider or a `feedback` prop turns it on,
// so components never gain side effects their primitives do not have.
const FeedbackContext = createContext<FeedbackSettings>({
  haptics: false,
  sound: false,
});

function FeedbackProvider({
  haptics = false,
  sound = false,
  children,
}: Partial<FeedbackSettings> & { children?: ReactNode }) {
  return (
    <FeedbackContext value={{ haptics, sound }}>{children}</FeedbackContext>
  );
}

const SILENT: FeedbackSettings = { haptics: false, sound: false };

function resolveFeedback(
  option: FeedbackOption | undefined,
  defaults: FeedbackSettings,
): FeedbackSettings {
  if (option === undefined) return defaults;
  if (option === true) return { haptics: true, sound: true };
  if (option === "haptic") return { haptics: true, sound: false };
  if (option === "sound") return { haptics: false, sound: true };
  return SILENT;
}

/**
 * Resolves whether haptics and sound are on, for components such as WheelPicker
 * that voice themselves but still follow the shared `feedback` switch.
 */
function useFeedbackSettings(option?: FeedbackOption, { optIn = false } = {}) {
  const context = use(FeedbackContext);
  return resolveFeedback(option, optIn ? SILENT : context);
}

/**
 * Returns a stable `trigger(kind, sound)` for a component's feedback moments;
 * `sound: false` keeps it to haptics for components that voice themselves.
 * Pass `optIn` for controls such as Button that should stay silent unless the
 * caller sets `feedback` explicitly.
 */
function useFeedback(option?: FeedbackOption, { optIn = false } = {}) {
  const settings = useFeedbackSettings(option, { optIn });
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  // Players are created on the first sound so silent controls never touch
  // Web Audio, and each one releases its share of the page context on unmount.
  const players = useRef(new Map<TickVariant, TickPlayer>());
  useEffect(() => {
    const current = players.current;
    return () => {
      for (const player of current.values()) player.dispose();
      current.clear();
    };
  }, []);

  return useCallback((kind: HapticKind, sound: TickVariant | false = "tap") => {
    const { haptics, sound: soundOn } = settingsRef.current;
    if (haptics) haptic(kind);
    if (!soundOn || !sound) return;
    let player = players.current.get(sound);
    if (!player) {
      player = createTickPlayer(sound);
      players.current.set(sound, player);
    }
    player.play();
  }, []);
}

export { FeedbackProvider, useFeedback, useFeedbackSettings };

"use client";

import { cn } from "cn";
import { canonicalD, type Morph } from "morphicons/dom";
import type { IconInput, SpringPreset } from "morphicons/react";
import { MorphIcon as MorphIconPrimitive } from "morphicons/react";
import type { ComponentProps } from "react";

type MorphIconProps = ComponentProps<typeof MorphIconPrimitive>;

function MorphIcon({
  className,
  size = 16,
  strokeWidth = 2,
  spring = "snappy",
  reducedMotion = "user",
  ...props
}: MorphIconProps) {
  return (
    <MorphIconPrimitive
      size={size}
      strokeWidth={strokeWidth}
      spring={spring}
      reducedMotion={reducedMotion}
      className={cn("shrink-0", className)}
      {...props}
    />
  );
}

export type {
  IconInput,
  IconNode,
  MorphHandle,
} from "morphicons/react";
export type { MorphIconProps };
export { MorphIcon };

function morphToCompletion(
  morph: Morph,
  path: SVGPathElement,
  icon: IconInput,
  spring: SpringPreset = "snappy",
) {
  let frame = 0;
  let settled = false;
  let finish: (completed: boolean) => void = () => {};
  const finished = new Promise<boolean>((resolve) => {
    finish = resolve;
  });
  const complete = (completed: boolean) => {
    if (settled) return;
    settled = true;
    cancelAnimationFrame(frame);
    document.removeEventListener("visibilitychange", visibilityChanged);
    finish(completed);
  };
  const endpoint = canonicalD(icon);
  morph.morphTo(icon, spring);
  const check = () => {
    if (
      document.hidden ||
      (morph.reducedMotion === "user" &&
        typeof matchMedia === "function" &&
        matchMedia("(prefers-reduced-motion: reduce)").matches)
    )
      morph.set(icon);
    // progress can still be 1 before the first spring frame. The canonical
    // endpoint is only painted when the driver really settles or motion is off.
    if (morph.progress === 1 && path.getAttribute("d") === endpoint)
      complete(true);
    else frame = requestAnimationFrame(check);
  };
  const visibilityChanged = () => {
    if (document.hidden) {
      morph.set(icon);
      complete(true);
    }
  };
  document.addEventListener("visibilitychange", visibilityChanged);
  check();
  return { finished, cancel: () => complete(false) };
}

export { createMorph, type Morph } from "morphicons/dom";
export { morphToCompletion };

"use client";

import { useEffect, useRef, useState } from "react";
import { type FeedbackOption, useFeedback } from "@/components/ui/feedback";

type ClipboardStatus = "idle" | "pending" | "copied" | "error";
/** English defaults. Pass overrides or `clipboardLabelsZhCN` through `labels`. */
const clipboardLabels = {
  copy: "Copy",
  pending: "Copying…",
  copied: "Copied",
  copyFailed: "Copy failed",
};
const clipboardLabelsZhCN: ClipboardLabels = {
  copy: "复制",
  pending: "正在复制…",
  copied: "已复制",
  copyFailed: "复制失败",
};
type ClipboardLabels = Partial<typeof clipboardLabels>;
type ClipboardOptions = {
  disabled?: boolean;
  resetDelay?: number;
  onCopy?: (value: string) => void;
  onCopyError?: (error: Error) => void;
  /** Haptics for a finished copy; follows `FeedbackProvider` when unset. */
  feedback?: FeedbackOption;
  labels?: ClipboardLabels;
};
type ClipboardControllerOptions = Omit<
  ClipboardOptions,
  "disabled" | "feedback" | "labels"
> & {
  writeText: (value: string) => Promise<void>;
  onStatusChange: (status: ClipboardStatus) => void;
};

// The controller owns each async attempt, so late results never update a newer
// value, a second attempt, or an unmounted component.
function createClipboardController(options: ClipboardControllerOptions) {
  let active = true;
  let pending = false;
  let attempt = 0;
  let copiedValue: string | undefined;
  let timer: ReturnType<typeof setTimeout> | undefined;
  const clear = () => {
    if (timer !== undefined) clearTimeout(timer);
    timer = undefined;
  };
  const reset = () => {
    attempt++;
    pending = false;
    copiedValue = undefined;
    clear();
    if (active) options.onStatusChange("idle");
  };
  return {
    activate() {
      active = true;
    },
    reset,
    synchronize(value: string) {
      // An uncontrolled input can synchronize after copying its live DOM value.
      if (value !== copiedValue) reset();
    },
    dispose() {
      active = false;
      attempt++;
      pending = false;
      copiedValue = undefined;
      clear();
    },
    async copy(value: string): Promise<boolean> {
      if (!active || pending) return false;
      const current = ++attempt;
      copiedValue = value;
      pending = true;
      clear();
      options.onStatusChange("pending");
      try {
        await options.writeText(value);
      } catch (reason) {
        if (!active || current !== attempt) return false;
        pending = false;
        const error =
          reason instanceof Error ? reason : new Error(String(reason));
        options.onStatusChange("error");
        options.onCopyError?.(error);
        return false;
      }
      if (!active || current !== attempt) return false;
      pending = false;
      options.onStatusChange("copied");
      const delay = options.resetDelay ?? 1500;
      timer = setTimeout(
        () => {
          timer = undefined;
          if (active && current === attempt) options.onStatusChange("idle");
        },
        Number.isFinite(delay) ? Math.max(0, delay) : 1500,
      );
      options.onCopy?.(value);
      return true;
    },
  };
}

function useClipboard(value: string, options: ClipboardOptions = {}) {
  const [status, setStatus] = useState<ClipboardStatus>("idle");
  const optionsRef = useRef(options);
  optionsRef.current = options;
  const trigger = useFeedback(options.feedback);
  const [controller] = useState(() =>
    createClipboardController({
      writeText: async (text) => {
        if (
          typeof navigator === "undefined" ||
          !navigator.clipboard?.writeText
        ) {
          throw new Error(
            "Clipboard access is unavailable. Select and copy the text manually.",
          );
        }
        await navigator.clipboard.writeText(text);
      },
      onStatusChange: setStatus,
      onCopy: (text) => {
        trigger("success");
        optionsRef.current.onCopy?.(text);
      },
      onCopyError: (error) => {
        trigger("error");
        optionsRef.current.onCopyError?.(error);
      },
      get resetDelay() {
        return optionsRef.current.resetDelay;
      },
    }),
  );
  useEffect(() => {
    controller.activate();
    return () => controller.dispose();
  }, [controller]);
  useEffect(() => {
    if (options.disabled) controller.reset();
    else controller.synchronize(value);
  }, [controller, value, options.disabled]);
  const text = { ...clipboardLabels, ...options.labels };
  return {
    status,
    /** The label for the current status: the copy action while idle. */
    message: {
      idle: text.copy,
      pending: text.pending,
      copied: text.copied,
      error: text.copyFailed,
    }[status],
    copy: (text = value) =>
      options.disabled ? Promise.resolve(false) : controller.copy(text),
    reset: controller.reset,
  };
}

export type { ClipboardLabels, ClipboardOptions, ClipboardStatus };
export {
  clipboardLabels,
  clipboardLabelsZhCN,
  createClipboardController,
  useClipboard,
};

// Fires a short system haptic, modeled on UIKit's feedback generators.
// Android and other browsers with the Vibration API get a timed pattern.
// iOS Safari has no Vibration API, but since iOS 18 toggling an
// `<input type="checkbox" switch>` plays the system Taptic click; clicking a
// hidden label for one is the only way a web page can reach the Taptic Engine.
// Both paths only work inside a user gesture, and everything else is a no-op.

export type HapticKind =
  | "selection"
  | "light"
  | "medium"
  | "heavy"
  | "success"
  | "warning"
  | "error";

const PATTERNS: Record<HapticKind, number | number[]> = {
  selection: 6,
  light: 10,
  medium: 16,
  heavy: 24,
  success: [10, 70, 14],
  warning: [16, 90, 16],
  error: [14, 50, 14, 50, 20],
};

// The iOS switch click has a single strength, so notification kinds are told
// apart by how many clicks they play.
const PULSES: Record<HapticKind, number> = {
  selection: 1,
  light: 1,
  medium: 1,
  heavy: 1,
  success: 2,
  warning: 2,
  error: 3,
};

const PULSE_GAP = 70; // milliseconds between iOS clicks

let label: HTMLLabelElement | null = null;

function getSwitchLabel(): HTMLLabelElement {
  if (label?.isConnected) return label;
  label = document.createElement("label");
  label.ariaHidden = "true";
  label.style.cssText =
    "position:fixed;width:1px;height:1px;overflow:hidden;opacity:0;pointer-events:none;clip-path:inset(50%)";
  const input = document.createElement("input");
  input.type = "checkbox";
  input.tabIndex = -1;
  input.setAttribute("switch", "");
  label.append(input);
  document.body.append(label);
  return label;
}

function canVibrate(): boolean {
  return typeof navigator.vibrate === "function";
}

// Only touch devices without the Vibration API take the switch path, so
// desktop browsers never pay for the hidden element.
function canTapticSwitch(): boolean {
  return window.matchMedia("(pointer: coarse)").matches;
}

export function haptic(kind: HapticKind = "selection") {
  if (typeof window === "undefined") return;
  try {
    if (canVibrate()) {
      navigator.vibrate(PATTERNS[kind]);
      return;
    }
    if (!canTapticSwitch()) return;
    const target = getSwitchLabel();
    target.click();
    for (let i = 1; i < PULSES[kind]; i++) {
      window.setTimeout(() => target.click(), PULSE_GAP * i);
    }
  } catch {
    // Haptics are decoration; a blocked API must never break the interaction.
  }
}

